package com.trampolim.api.geography;
import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import com.trampolim.api.company.CompanyRadarController;
@RestController @ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true") public class RegionalCompanyController {
 private final JdbcTemplate jdbc;private final TerritorialCatalog geo;public RegionalCompanyController(@Qualifier("empresasJdbcTemplate")JdbcTemplate jdbc,TerritorialCatalog geo){this.jdbc=jdbc;this.geo=geo;}
 @GetMapping("/api/public/companies/regional-opportunities")public Map<String,Object> list(@RequestParam(defaultValue="")String region,@RequestParam(defaultValue="")String municipalityCode,@RequestParam(defaultValue="true")boolean includeRemote,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String city,@RequestParam(defaultValue="")String area,@RequestParam(defaultValue="")String modality,@RequestParam(defaultValue="false")boolean internshipsOnly,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit,@RequestParam Map<String,String> parameters){String kind=parameters.getOrDefault("kind","job");if(!Set.of("job","course").contains(kind))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Tipo de catálogo inválido.");var filter=RegionalQuery.filter(geo,new RegionalQuery.Filters(region,municipalityCode,includeRemote,q,city,area,modality,before,limit),"l",true);filter=SearchRefinements.apply(geo,filter,parameters,true);var args=new ArrayList<Object>(filter.args());args.add(limit+1);var rows=jdbc.queryForList("SELECT l.id,c.public_slug AS \"companySlug\",c.trade_name AS \"companyName\",l.title,l.area,l.description,l.requirements,l.location,l.municipality_code AS \"municipalityCode\",l.modality,l.salary,l.accepted_courses AS \"acceptedCourses\",l.work_schedule AS \"workSchedule\",l.workload,l.benefits,l.headcount AS quantity,l.application_deadline AS \"applicationDeadline\",c.public_slug AS slug,l.contract_type AS \"contractType\",l.expires_at AS \"expiresAt\",l.is_internship AS internship FROM company_listings l JOIN companies c ON c.id=l.company_id WHERE "+CompanyRadarController.PUBLIC_JOB_CONDITION.replace("l.kind='job'",kind.equals("course")?"l.kind='course'":"l.kind='job'")+(internshipsOnly?" AND l.is_internship=TRUE":"")+filter.where()+" ORDER BY l.id DESC LIMIT ?",args.toArray());for(var row:rows)row.put("municipalityLabel",geo.label(row.get("municipalityCode")));return RegionalQuery.page(rows,limit);}
 @GetMapping("/api/company/listings/{id}/municipality")public Map<String,Object> current(@AuthenticationPrincipal String email,@PathVariable long id){var rows=jdbc.queryForList("SELECT l.municipality_code FROM company_listings l JOIN company_members m ON m.company_id=l.company_id JOIN company_users u ON u.id=m.user_id WHERE l.id=? AND LOWER(u.email)=LOWER(?) AND u.email_verified=TRUE AND u.account_status='ACTIVE' AND m.role IN ('OWNER','RECRUITER')",id,email);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var result=new LinkedHashMap<String,Object>();result.put("municipality",rows.get(0).get("municipality_code")==null?null:geo.municipality(rows.get(0).get("municipality_code").toString()));return result;}
 @PutMapping("/api/company/listings/{id}/municipality")@ResponseStatus(HttpStatus.NO_CONTENT)@org.springframework.transaction.annotation.Transactional("empresasTransactionManager")public void assign(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody RegionalCatalogController.Assignment input){if(input==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST);String code=input.municipalityCode();if(code!=null&&!code.isBlank())geo.municipality(code);else code=null;var owners=jdbc.queryForList("SELECT l.company_id,u.id AS actor FROM company_listings l JOIN company_members m ON m.company_id=l.company_id JOIN company_users u ON u.id=m.user_id WHERE l.id=? AND LOWER(u.email)=LOWER(?) AND u.email_verified=TRUE AND u.account_status='ACTIVE' AND m.role IN ('OWNER','RECRUITER') FOR UPDATE OF l",id,email);if(owners.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Vaga não encontrada ou sem permissão de edição.");jdbc.update("UPDATE company_listings SET municipality_code=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",code,id);jdbc.update("INSERT INTO company_audit_events(company_id,actor_user_id,event_type) VALUES (?,?,'LISTING_MUNICIPALITY_ASSIGNED')",owners.get(0).get("company_id"),owners.get(0).get("actor"));}
}
